        // help
        ["Help"] = "Help",
        ["Close (F1)"] = "Sluiten (F1)",
        ["Wizard"] = "Wizard",
        ["Coworkee Studio writes an app spec, the JSON the coworkee CLI takes, and lets the CLI create the app. Every page changes one part of the spec; the panel on the left shows where you are and takes you back to any page you have seen."] = "Coworkee Studio schrijft een app-specificatie, de JSON die de coworkee-CLI gebruikt, en laat de CLI de app aanmaken. Elke pagina wijzigt een deel van de specificatie; het paneel links toont waar je bent en brengt je terug naar elke pagina die je al hebt gezien.",
        ["Keyboard"] = "Toetsenbord",
        ["Start options"] = "Startopties",
        ["Coworkee Studio in the documentation"] = "Coworkee Studio in de documentatie",
        ["The Studio runs coworkee spec validate and coworkee new --spec. Everything it does works in a terminal as well:"] = "De Studio voert coworkee spec validate en coworkee new --spec uit. Alles wat hij doet, werkt ook in een terminal:",
        ["All commands and switches"] = "Alle commando's en schakelaars",
        ["coworkee mcp runs a Model Context Protocol server over stdio. An AI agent such as Claude Code, Claude Desktop or Copilot in VS Code can then plan an app with you, write its spec, create it and add modules, entities and migrations, with the same commands as this Studio."] = "coworkee mcp draait een Model Context Protocol-server via stdio. Een AI-agent zoals Claude Code, Claude Desktop of Copilot in VS Code kan dan samen met je een app plannen, de specificatie schrijven, de app aanmaken en modules, entiteiten en migraties toevoegen, met dezelfde commando's als deze Studio.",
        ["This is the MCP server of the command line on your machine. A generated app has its own MCP endpoint under /mcp with the tools of the app (AI assistant module)."] = "Dit is de MCP-server van de opdrachtregel op je computer. Een gegenereerde app heeft een eigen MCP-endpoint onder /mcp met de tools van de app (module AI-assistent).",
        ["Claude Desktop (claude_desktop_config.json) and other clients with mcpServers"] = "Claude Desktop (claude_desktop_config.json) en andere clients met mcpServers",
        ["Tools"] = "Tools",
        ["Try it"] = "Probeer het",
        ["The agent reads list_options and get_spec_schema, writes a spec with a Sales module, checks it with validate_spec and calls create_app."] = "De agent leest list_options en get_spec_schema, schrijft een specificatie met een Sales-module, controleert die met validate_spec en roept create_app aan.",
        ["The MCP server in the documentation"] = "De MCP-server in de documentatie",
