        ["One file for app, tab and sign-in"] = "Eén bestand voor app, tabblad en aanmelding",
        ["SVG scales best"] = "SVG schaalt het best",
        ["Sign-in layout"] = "Aanmeldlay-out",
        ["Layout of the sign-in pages."] = "Lay-out van de aanmeldpagina's.",
        ["Split for a full-page image or video, Card for a plain look."] = "Split voor een paginavullende afbeelding of video, Kaart voor een eenvoudige stijl.",
        ["Changeable later on the Themes page"] = "Later te wijzigen op de pagina Thema's",
        ["A centered card."] = "Een gecentreerde kaart.",
