        ["Sign-in media"] = "Aanmeldmedia",
        ["Image or video next to the sign-in form: a local file (copied into the web client) or an http(s) address."] = "Afbeelding of video naast het aanmeldformulier: een lokaal bestand (gekopieerd naar de webclient) of een http(s)-adres.",
        ["With the Split or Slide layout."] = "Met de lay-out Split of Schuiven.",
        ["With the Split or Slide layout, or as background of the loading screen."] = "Met de lay-out Split of Schuiven, of als achtergrond van het laadscherm.",
